// Singleton upsert: fetch existing row id, update if exists, else insert
const [existingSettingsQh] = await sql<{ id: string }[]>`
  SELECT id FROM notification_settings LIMIT 1
`;
if (existingSettingsQh) {
  await sql`
    UPDATE notification_settings
    SET quiet_hours_start = ${safeStart},
        quiet_hours_end = ${safeEnd},
        timezone = ${safeTz},
        updated_at = now()
    WHERE id = ${existingSettingsQh.id}
  `;
} else {
  await sql`
    INSERT INTO notification_settings (
      notification_subject_template, notification_body_template,
      quiet_hours_start, quiet_hours_end, timezone, updated_at
    ) VALUES (
      '{{product_name}} is back in stock!',
      '<p>Great news! {{item_detail}} is back in stock.</p>',
      ${safeStart}, ${safeEnd}, ${safeTz}, now()
    )
  `;
}
